const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// All pictures share a fixed physical scale. Geometry is the exact model, not a hit target.
export function ribbonLine({cuts=[],markerIndex=null,label='Our ribbon trail',guides=false}={}){
 const boundaries=[0,...cuts,12,...cuts.map(n=>n+12),24], x=t=>45+t*810/24;
 const flag=Number.isInteger(markerIndex)?boundaries[markerIndex]:null;
 return `<svg class="fraction-line" viewBox="0 0 900 220" role="img" aria-label="${esc(label)}. Line from zero to two. The first whole is bracketed. ${cuts.length+1} spaces in each whole. ${flag===null?'No flag placed.':`Flag is ${markerIndex} ${markerIndex===1?'space':'spaces'} from zero.`}"><path class="fraction-unit-bracket" d="M45 47V33H450V47"/><text x="247.5" y="22" text-anchor="middle">one whole ribbon</text><path class="fraction-second-bracket" d="M450 47V33H855V47"/><text x="652.5" y="22" text-anchor="middle">another whole</text><rect x="45" y="92" width="810" height="34" rx="2" class="fraction-ribbon"/>${guides?Array.from({length:11},(_,i)=>i+1).filter(t=>!cuts.includes(t)).flatMap(t=>[t,t+12]).map(t=>`<path class="fraction-faint-guide" d="M${x(t)} 85V133"/>`).join(''):''}${boundaries.map(t=>`<path class="${t%12===0?'fraction-whole-boundary':'fraction-cut'}" d="M${x(t)} ${t%12===0?80:90}V${t%12===0?143:130}"/>`).join('')}${[0,12,24].map((t,i)=>`<text class="fraction-number" x="${x(t)}" y="169" text-anchor="middle">${i}</text>`).join('')}${flag===null?'':`<g class="fraction-flag" transform="translate(${x(flag)} 91)"><path d="M0 0V-41L30-31L0-20"/><circle cy="18" r="7"/></g>`}<text x="45" y="202">start</text></svg>`;
}
export function guidePreview(t){return `<svg viewBox="0 0 90 32" aria-hidden="true"><path d="M5 20H85M5 13V27M85 13V27" stroke="currentColor" fill="none"/><path d="M${5+t*80/12} 6V29" stroke="currentColor" stroke-width="3"/><circle cx="${5+t*80/12}" cy="6" r="3" fill="currentColor"/></svg>`;}
export function changedWholeArt(){return `<svg class="fraction-changed-whole" viewBox="0 0 900 295" role="img" aria-label="Ribbon A and ribbon B share a left edge and display scale. Ribbon B is twice as long. The left half of each is marked; half of ribbon B is longer."><g class="fraction-unit-bracket"><path d="M45 47V35H450V47M45 181V169H855V181"/></g><text x="247.5" y="23" text-anchor="middle">one whole ribbon A</text><text x="450" y="157" text-anchor="middle">one whole ribbon B</text><rect x="45" y="61" width="202.5" height="35" class="fraction-half"/><rect x="45" y="61" width="405" height="35" class="fraction-whole-outline"/><path class="fraction-cut" d="M247.5 61V96"/><text x="146.25" y="120" text-anchor="middle">half of ribbon A</text><rect x="45" y="195" width="405" height="35" class="fraction-half"/><rect x="45" y="195" width="810" height="35" class="fraction-whole-outline"/><path class="fraction-cut" d="M450 195V230"/><text x="247.5" y="254" text-anchor="middle">half of ribbon B</text></svg>`;}
